{
  "technical_and_design_decisions": [
    "Each migrated module is restructured as a Spring Cloud Stream app starter: a Spring Boot auto-configuration plus an executable application, bound to a message broker via the Spring Cloud Stream binder abstraction (@EnableBinding Source/Sink/Processor).",
    "Implementation reuses Spring Integration components where possible (spring-integration-mqtt for mqtt, spring-integration-ip for tcp, spring-integration-jdbc for jdbc, Spring Integration aggregator for aggregator, HTTP outbound gateway for http-client), since the original Spring XD modules were already Spring Integration based.",
    "All module options are externalized as Spring Boot @ConfigurationProperties classes with spring-boot-configuration-processor to generate configuration metadata (replacing XD module descriptor XML files).",
    "Maven multi-module build with a shared parent POM and a BOM for dependency management; Java 17 baseline per the stated Spring Framework 6 requirement.",
    "Aggregator state store uses a pluggable abstraction with an in-memory default store plus JDBC/Redis-backed options; correlation and release strategies are configurable via properties.",
    "Testing stack: JUnit 5, Spring Boot Test, and embedded/test-scoped infrastructure (embedded MQTT broker, H2 database, WireMock for HTTP, real socket servers for TCP/shell) so integration tests run self-contained in CI.",
    "Each starter is packaged as an executable Spring Boot fat jar; documentation is provided as Asciidoc/README per module.",
    "No XD-specific runtime (dirt, module registry) is retained; XD container features are replaced by Spring Boot auto-configuration and Spring Cloud Stream binding."
  ],
  "assumptions": [
    "The Spring XD source code for all eight modules is available and its open-source license permits copying and adaptation into the s-c-s repository.",
    "A single developer performs all work; effort is expressed in workdays of 8 hours and excludes elapsed calendar effects such as waiting on reviews or CI queues.",
    "For 'move' stories (U1–U6), module logic is largely reused with packaging and configuration adaptation; for 'port' stories (U7–U8), logic must be adapted to the processor (request-reply / stateful) model, which requires more rework.",
    "The s-c-s repository, CI system, and artifact publishing infrastructure already exist; only build configuration within the repo is in scope.",
    "External systems needed by sinks/sources (MQTT broker, Splunk instance, databases, TCP endpoints) are available for development and testing via embedded servers, test containers, or existing test environments, so no infrastructure provisioning effort is included.",
    "Per-module estimates include unit tests, integration tests, code review rework, and module-level documentation.",
    "No performance, load, or soak testing is required; functional correctness and broker-agnostic integration tests are sufficient for acceptance.",
    "Splunk integration targets the Splunk HTTP Event Collector (HEC) or the official Splunk Java SDK; credentials and endpoint are configurable properties.",
    "The null sink simply discards consumed messages (logging at debug level), making it a trivial module.",
    "No changes to the Spring Cloud Stream core framework itself are needed; only the app starter modules are delivered."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Module analysis and migration planning",
      "activity_description": "Analyze the eight Spring XD modules (dependencies, channel adapters, options metadata, tests), map XD options to Spring Boot configuration properties, and define the migration approach per module.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "A2",
      "activity_name": "Repository and build infrastructure setup",
      "activity_description": "Set up the multi-module Maven structure in the s-c-s repo: parent POM, BOM, shared build plugins, Java 17 toolchain, CI build configuration, and a starter skeleton/template reused by all modules.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "A3",
      "activity_name": "Migrate mqtt sink module (U1)",
      "activity_description": "Port the XD mqtt sink to a Spring Cloud Stream sink using spring-integration-mqtt: auto-configuration, connection/topic/QoS configuration properties, unit tests, integration test with an embedded MQTT broker, and documentation.",
      "most_likely_effort": 4.0
    },
    {
      "activity_id": "A4",
      "activity_name": "Migrate null sink module (U2)",
      "activity_description": "Port the trivial XD null sink (message discarding consumer) to a Spring Cloud Stream sink, including auto-configuration, unit test, and minimal documentation.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A5",
      "activity_name": "Migrate shell sink module (U3)",
      "activity_description": "Port the XD shell sink to a Spring Cloud Stream sink: execute configurable shell commands with the message payload as input, handle working directory, environment, timeout and charset options, unit and integration tests, and documentation.",
      "most_likely_effort": 3.0
    },
    {
      "activity_id": "A6",
      "activity_name": "Migrate splunk sink module (U4)",
      "activity_description": "Port the XD splunk sink to a Spring Cloud Stream sink using the Splunk HEC/SDK: endpoint, token, index/source/sourcetype configuration, error handling and retry, unit tests, integration test against a stubbed Splunk endpoint, and documentation.",
      "most_likely_effort": 5.0
    },
    {
      "activity_id": "A7",
      "activity_name": "Migrate tcp sink module (U5)",
      "activity_description": "Port the XD tcp sink to a Spring Cloud Stream sink using spring-integration-ip: connection factory, host/port, serializer/deserializer (CRLF, length header) options, unit tests, integration test against a real socket server, and documentation.",
      "most_likely_effort": 4.0
    },
    {
      "activity_id": "A8",
      "activity_name": "Migrate jdbc source module (U6)",
      "activity_description": "Port the XD jdbc source to a Spring Cloud Stream source using spring-integration-jdbc: configurable polling query, update query, max rows, DataSource auto-configuration, unit tests, integration tests against an embedded H2 database, and documentation.",
      "most_likely_effort": 6.0
    },
    {
      "activity_id": "A9",
      "activity_name": "Port aggregator processor module (U7)",
      "activity_description": "Port the XD aggregator module to a Spring Cloud Stream processor: adapt aggregation logic to the processor model, implement correlation/release strategies, pluggable message store (in-memory default, JDBC/Redis options), timeout handling, unit tests, integration tests with a binder test harness, and documentation.",
      "most_likely_effort": 8.0
    },
    {
      "activity_id": "A10",
      "activity_name": "Port http-client processor module (U8)",
      "activity_description": "Port the XD http-client module to a Spring Cloud Stream processor: map incoming messages to HTTP requests (URL, method, headers, body expressions), map responses to output messages, error handling, unit tests, integration tests with WireMock, and documentation.",
      "most_likely_effort": 4.0
    },
    {
      "activity_id": "A11",
      "activity_name": "Cross-module integration verification and release packaging",
      "activity_description": "Verify all eight starters together in end-to-end pipelines with a test binder/broker, align versions in the BOM, finalize reference documentation, and prepare release artifacts.",
      "most_likely_effort": 2.0
    }
  ],
  "reported_total": {
    "most_likely_effort": 41.0
  }
}

